	});

	it("reads an HTML body on a 200 the same way", async () => {
		const fetchImpl = vi.fn(() =>
			Promise.resolve(reply("<!DOCTYPE html><html>...</html>")),
		);

		await expect(
			client(fetchImpl as unknown as typeof fetch).get(7),
