414	/** Map an ADO HTTP failure onto the tasks-axi error vocabulary. */
415	export function adoError(status: number, body: string): AxiError {
416		let message = body.slice(0, 500);
417		try {
418			const parsed = JSON.parse(body) as { message?: string };
419			if (parsed.message) message = parsed.message;
420		} catch {
421			// Non-JSON error body: keep the truncated text.
422		}
423		let error: AxiError;
424		if (status === 401 || status === 403) {
425			error = new AxiError(
426				`Azure DevOps rejected the credential (${status}): ${message}`,
427				"VALIDATION_ERROR",
428				[
429					`export ${PAT_ENV_VARS[0]}=<pat> with Work Items (read & write) scope`,
430					"Or run `az login` for a bearer token",
431				],
432			);
433		} else if (status === 404) {
434			error = new AxiError(message, "NOT_FOUND");
435		} else if (status === 409 || status === 412) {
436			error = new AxiError(message, "CONFLICT");
437		} else if (status === 400) {
438			error = new AxiError(message, "VALIDATION_ERROR");
439		} else {
440			error = new AxiError(
441				`Azure DevOps request failed (${status}): ${message}`,
442				"UNKNOWN",
443			);
444		}
445		return status >= 400 && status < 500 ? definitive(error) : error;
446	}
